			hint = "协助哨兵对抗焦炭谷的燃烧之灵。",
			text = [=[凯拉第一次见到{link:the-charred-vale}焦炭谷{/link}时，几乎落泪。地精们不仅烧毁了树木。他们愚蠢地释放了火焰、岩石和怒火的{link:elements}元素{/link}，她说，只要这些灵体还在{link:stranglethorn-vale}山谷{/link}中游荡，这片土地就没有机会看到艾露恩的微笑。]=],
