Translate("zhCN", "gaxim-rustfizzle", {
	title = "加克希姆·尘链",
	subtitle = "启迪协会的侏儒",
	found = "在狂风峭壁西部边缘，凯拉·影矛身旁",
	hint = "寻找在狂风峭壁上方与哨兵一同工作的侏儒。",
	allegiance = "诺莫瑞根流亡者 · 奥术学、炼金术与工程学启迪协会",
	aliases = { "加克希姆" },
	sections = {
		{
			title = "概述",
			text = [=[加克希姆·尘链是一名{link:gnomes}侏儒{/link}法师兼工匠，也是一个名字极长的学术团体的骄傲成员：奥术学、炼{link:ginro-hearthkindle}金{/link}术与工程学启迪协会。他与{link:sentinels}哨兵{/link}{link:kaela-shadowspear}凯拉·影矛{/link}一同来到{link:stonetalon-mountains}石爪{/link}。他以自己小小身躯的全部力量坚信，魔法、混合药剂和机械的结合能够拯救{link:night-elves}暗夜精灵{/link}的森林。他打算用炸药来证明这一点。]=],
		},
		{
			title = "意义",
			text = [=[加克希姆代表着一种{link:night-elves}卡多雷{/link}长期抗拒的观念：魔法和技艺若运用得当，可以服务于森林而不是伤害它。他公开表示，暗夜精灵需要魔法，世界也需要魔法。他对{link:venture-company}风险投资公司{/link}的战争就是他的论据。]=],
		},
		{
			title = "事迹",
			text = [=[• 他沿着山脉边缘精心布置爆破，将地精逼退。
• 他用一种稀有化合物NG-5和一道传讯法术设计了遥控炸药。
• 他策划了两次对{link:venture-company}风险投资公司{/link}的突袭，一次为了它的工程图纸，一次为了它的信件。
• 他研究从{link:the-charred-vale}焦炭谷{/link}被腐化的树人身上取下的弹片。]=],
		},
	},
	chapters = {
		{
			title = "遥控引爆",
			hint = "收集侏儒的爆炸装置所需之物。",
			text = [=[加克希姆的计划需要两样他自己做不出来的东西。第一样是硝基米尔甘油素，即NG-5，只有他在{link:tinker-town}侏儒区{/link}的老同事洛玛克·链带能够调配。第二样是一道能让炸药从远处引爆的法术，为此他写信给{link:stormwind-city}暴风城{/link}的法师科林·玛伦。当两样东西都到手后，加克希姆宣布他的装置已经完美。一车车炸药已经准备就绪。]=],
		},
		{
			title = "秘密行动",
			hint = "执行侏儒对付风险投资公司的计划。",
			text = [=[加克希姆坚称，爆炸从来不是重点。它们只是声东击西。趁地精们惊慌乱窜之际，真正的目标被夺走了：{link:cragpool-lake}峭壁湖{/link}南面伐木场里的工程图纸，以及公司的私人信件。加克希姆希望借此找出地精机器的弱点，或许还能顺便借用它们的几个设计。]=],
		},
	},
	mentions = {
