		{ text = "{link:kaela-shadowspear}凯拉{/link}的近况" },
		{ text = "{link:tyrande-whisperwind}泰兰德{/link}的接见，在突袭之后" },
		{ text = "卡斯派普的任务" },
	},
	bonds = {
		{ id = "kaela-shadowspear", name = "凯拉·影矛", note = "他在石爪的搭档" },
		{ id = "gerenzo-wrenchwhistle", name = "格雷苏", note = "站在另一边的侏儒" },
